import {ownRecord,denseValues} from './state-validation.mjs';
import {contextConcepts,contextFor} from './language-context-data.mjs';
import {mountLanguageAudio,stopLanguageAudio} from './language-audio.mjs';
const ids=contextConcepts.map(c=>c.id),positions=['Espacio 1','Espacio 2','Espacio 3'];
export const newLanguageScene=()=>({open:true,page:'edit',objects:[null,null,null],labels:[null,null,null],mode:'object',tool:'apple',reviewed:false,hint:false,original:null,previous:null});
function layout(raw){ownRecord(raw,['objects','labels']);const objects=denseValues(raw.objects,[null,...ids],3,true),labels=denseValues(raw.labels,[null,...ids],3,true);if(objects.some((x,i)=>x===null&&labels[i]!==null))throw Error('Label without object');return {objects,labels};}
export function validateLanguageScene(s){ownRecord(s,['open','page','objects','labels','mode','tool','reviewed','hint','original','previous']);const value=layout({objects:s.objects,labels:s.labels});if(typeof s.open!=='boolean'||!['edit','compare'].includes(s.page)||!['object','label'].includes(s.mode)||![null,...ids].includes(s.tool)||typeof s.reviewed!=='boolean'||typeof s.hint!=='boolean')throw Error('Invalid scene');const original=s.original===null?null:layout(s.original),previous=s.previous===null?null:layout(s.previous);if(original&&!original.objects.some(Boolean)||s.page==='compare'&&(!original||!value.objects.some(Boolean)||!s.reviewed))throw Error('Invalid scene phase');return {...s,...value,original,previous};}
export function placeScene(s,index){if(s.page!=='edit'||!Number.isInteger(index)||index<0||index>2||s.mode==='label'&&!s.objects[index]||(s.mode==='object'?s.objects[index]:s.labels[index])===s.tool)return false;s.previous={objects:[...s.objects],labels:[...s.labels]};if(s.mode==='object'){s.objects[index]=s.tool;if(s.tool===null)s.labels[index]=null;}else s.labels[index]=s.tool;s.reviewed=false;return true;}
export function undoScene(s){if(!s.previous||s.page!=='edit')return false;const p=s.previous;s.objects=[...p.objects];s.labels=[...p.labels];s.previous=null;s.reviewed=false;return true;}
export function saveSceneDraft(s){if(s.page!=='edit'||!s.objects.some(Boolean)||s.original)return false;s.original={objects:[...s.objects],labels:[...s.labels]};return true;}
export function reviewScene(id,s){const l=contextFor(id);if(!l)throw Error('Unknown scene language');return s.objects.map((object,i)=>{if(!object)return {kind:'empty',text:positions[i]+': espacio libre; puede quedarse así.'};const index=ids.indexOf(object),label=s.labels[i];return {kind:label===object?'match':label===null?'missing':'mismatch',text:positions[i]+': '+contextConcepts[index].label+'. '+(label===object?l.words[index]+' corresponde a este objeto.':label===null?'Puedes añadir la etiqueta '+l.words[index]+'.':'La etiqueta '+l.words[ids.indexOf(label)]+' nombra '+contextConcepts[ids.indexOf(label)].label+'; para este dibujo puedes usar '+l.words[index]+'.')};});}
export function renderLanguageScene(root,state,id,finish,{picture,back}){
 stopLanguageAudio(root.ownerDocument);const l=contextFor(id),s=state.contextScene;
 const word=value=>{const i=ids.indexOf(value);return i<0?'Sin etiqueta':`<span lang="${l.id}">${l.words[i]}</span>${l.pinyin?` <small lang="zh-Latn">${l.pinyin[i]}</small>`:''}`;};const name=value=>contextConcepts.find(c=>c.id===value)?.label||'espacio libre';
 const redraw=(focus='#scene-title')=>{renderLanguageScene(root,state,id,finish,{picture,back});root.querySelector(focus)?.focus();};
 const board=(value,editable)=>`<div class="language-scene-board">${value.objects.map((v,i)=>editable?`<button type="button" class="scene-slot" data-scene-slot="${i}" aria-label="${positions[i]}: ${name(v)}. Etiqueta: ${value.labels[i]?l.words[ids.indexOf(value.labels[i])]:'ninguna'}. ${s.mode==='object'?'Colocar objeto':'Colocar etiqueta'}"><strong>${positions[i]}</strong>${v?picture(v):'<span class="scene-empty" aria-hidden="true">＋</span>'}<span>${name(v)}</span><span class="scene-label">${word(value.labels[i])}</span></button>`:`<div class="scene-slot"><strong>${positions[i]}</strong>${v?picture(v):'<span class="scene-empty" aria-hidden="true">—</span>'}<span>${name(v)}</span><span class="scene-label">${word(value.labels[i])}</span></div>`).join('')}</div>`;
 const notes=()=>`<ul>${reviewScene(id,s).map(r=>`<li>${r.text}</li>`).join('')}</ul>`;
 root.innerHTML=`<section class="language-scene-studio"><p class="eyebrow">${l.name} · construir con tres palabras conocidas · 6–8 años con adulto</p><h4 id="scene-title" tabindex="-1">Mi escena con etiquetas</h4><p>Elige qué objetos colocar y dónde. Puedes repetirlos o dejar espacios libres. Las etiquetas nombran objetos; no construimos frases ni evaluamos pronunciación.</p>${s.page==='edit'?`<fieldset><legend>1 · Elige un objeto para colocar</legend><div class="scene-tools">${[...ids,null].map(v=>`<button type="button" class="action secondary" data-scene-object="${v??'empty'}" aria-pressed="${s.mode==='object'&&s.tool===v}">${v?picture(v):''}${v?name(v):'Quitar objeto y etiqueta'}</button>`).join('')}</div></fieldset><fieldset><legend>2 · O elige una etiqueta para un objeto que ya colocaste</legend><div class="scene-tools">${[...ids,null].map(v=>`<button type="button" class="action secondary" data-scene-label="${v??'empty'}" aria-pressed="${s.mode==='label'&&s.tool===v}">${v?word(v):'Quitar etiqueta'}</button>`).join('')}</div></fieldset><p id="scene-tool">Ahora: ${s.mode==='object'?'colocar '+name(s.tool):'etiquetar con '+(s.tool?l.words[ids.indexOf(s.tool)]:'ninguna palabra')}. Pulsa una casilla.</p>${board(s,true)}<div class="controls"><button type="button" class="action secondary" id="scene-undo" ${!s.previous?'disabled':''}>Deshacer último cambio</button><button type="button" class="action primary" id="scene-review">Revisar etiquetas</button><button type="button" class="action secondary" id="scene-hint">Una pista</button></div><div id="scene-feedback" role="status" tabindex="-1">${s.reviewed?notes():''}</div><p id="scene-hint-text" role="status" tabindex="-1">${s.hint?'El lugar y la cantidad los decides tú. Revisa una pareja dibujo–palabra cada vez: '+contextConcepts.map((c,i)=>c.label+' → '+l.words[i]).join('; ')+'.':''}</p>${!s.original?'<button type="button" class="action secondary" id="scene-save-draft">Conservar este primer diseño</button>':'<p>El primer diseño está conservado. Cambia objetos, etiquetas o posiciones y compara cuando quieras.</p><button type="button" class="action primary" id="scene-compare">Comparar mis diseños</button>'}`:`<h5>Primer diseño conservado</h5>${board(s.original,false)}<h5>Diseño actual</h5>${board(s,false)}<div class="notice">${notes()}</div><p>Puede haber distintas escenas con etiquetas que corresponden. Mantener tu diseño también es válido; las parejas pendientes siguen explicadas.</p><p><strong>Fuera de pantalla:</strong> dibuja tu escena y copia o señala una etiqueta con ayuda. Puedes consultar la guía. No necesitas comida real ni contar experiencias personales.</p><button type="button" class="action secondary" id="scene-revise">Revisar mi diseño</button>`}<div class="controls"><button type="button" class="action secondary" id="scene-back">Volver al recorrido de palabras</button><button type="button" class="action primary" id="scene-finish">Terminar por hoy</button></div></section>`;
 const on=(sel,fn)=>root.querySelector(sel)?.addEventListener('click',fn);
 for(const mode of ['object','label'])root.querySelectorAll(`[data-scene-${mode}]`).forEach(b=>b.onclick=()=>{s.mode=mode;s.tool=b.getAttribute('data-scene-'+mode)==='empty'?null:b.getAttribute('data-scene-'+mode);redraw(`[data-scene-${mode}="${s.tool??'empty'}"]`);});
 root.querySelectorAll('[data-scene-slot]').forEach(b=>b.onclick=()=>{if(placeScene(s,Number(b.dataset.sceneSlot)))redraw(`[data-scene-slot="${b.dataset.sceneSlot}"]`);else if(s.mode==='label'&&!s.objects[Number(b.dataset.sceneSlot)]){const e=root.querySelector('#scene-feedback');e.textContent='Primero coloca un objeto en esta casilla; después añade su etiqueta.';e.focus();}});
 on('#scene-review',()=>{s.reviewed=true;redraw('#scene-feedback');});on('#scene-hint',()=>{s.hint=true;redraw('#scene-hint-text');});on('#scene-undo',()=>{if(undoScene(s))redraw('[data-scene-slot="0"]');});
 on('#scene-save-draft',()=>{if(saveSceneDraft(s))redraw('#scene-compare');else{const e=root.querySelector('#scene-feedback');e.textContent='Coloca al menos un objeto para conservar un diseño.';e.focus();}});
 on('#scene-compare',()=>{if(s.objects.some(Boolean)&&s.reviewed){s.page='compare';redraw();}else{const e=root.querySelector('#scene-feedback');e.textContent='Mantén al menos un objeto y revisa las etiquetas antes de comparar. No hace falta que todas correspondan.';e.focus();}});
 on('#scene-revise',()=>{s.page='edit';redraw();});on('#scene-back',()=>{s.open=false;back();});on('#scene-finish',finish);mountLanguageAudio(root,id,[0,1,2]);
}
